) AS e(subject_table, object_domain, sub_relation)
JOIN llm.kg_entities a ON a.namespace = 2 AND a.name = e.subject_table
JOIN llm.kg_entities b ON b.namespace = 2 AND b.name = e.object_domain
WHERE NOT EXISTS (
    SELECT 1 FROM llm.kg_edges x
    WHERE x.namespace = 2
      AND x.relation  = 'labeled_by'
      AND x.sub_relation IS NOT DISTINCT FROM e.sub_relation
      AND x.entity_ids = ARRAY[a.entity_id, b.entity_id]::BIGINT[]
);
